namespace Pharma.Models;

public sealed class Utilisateur { public long Id { get; set; } public string Identifiant { get; set; } = ""; public string MotDePasseHache { get; set; } = ""; public RoleUtilisateur Role { get; set; } }
public sealed class Produit { public long Id { get; set; } public string Reference { get; set; } = ""; public string CodeBarres { get; set; } = ""; public string Designation { get; set; } = ""; public string Categorie { get; set; } = ""; public int SeuilStockMinimum { get; set; } public decimal PrixVente { get; set; } public bool IsArchive { get; set; } }
public sealed class Fournisseur { public long Id { get; set; } public string Nom { get; set; } = ""; public string? Telephone { get; set; } public string? Email { get; set; } public string? Adresse { get; set; } public bool IsArchive { get; set; } }
public sealed class Lot { public long Id { get; set; } public long ProduitId { get; set; } public string NumeroLot { get; set; } = ""; public DateTime DatePeremption { get; set; } public int QuantitePhysique { get; set; } public int QuantiteVendable { get; set; } public decimal CoutAchat { get; set; } public bool IsBloque { get; set; } }
public sealed class Vente { public long Id { get; set; } public DateTime DateVente { get; set; } = DateTime.Now; public ModePaiement ModePaiement { get; set; } public long UtilisateurId { get; set; } public long? SessionId { get; set; } public decimal Total { get; set; } }
public sealed class LigneVente { public long Id { get; set; } public long VenteId { get; set; } public long ProduitId { get; set; } public long LotId { get; set; } public int Quantite { get; set; } public decimal PrixVente { get; set; } }
public sealed class MouvementStock { public long Id { get; set; } public DateTime DateMouvement { get; set; } = DateTime.Now; public long LotId { get; set; } public int Quantite { get; set; } public MotifMouvement Motif { get; set; } public long UtilisateurId { get; set; } }
public sealed class LogAction { public long Id { get; set; } public DateTime DateLog { get; set; } = DateTime.Now; public long? UtilisateurId { get; set; } public string DescriptionAction { get; set; } = ""; }
public sealed record AlerteStock(string Type, string Message, long ProduitId, long? LotId = null);
public sealed class Reception { public long Id { get; set; } public DateTime DateReception { get; set; } = DateTime.Now; public long? FournisseurId { get; set; } public string? ReferenceDocument { get; set; } public long UtilisateurId { get; set; } public string Statut { get; set; } = "Validee"; }
public sealed class LigneReception { public long Id { get; set; } public long ReceptionId { get; set; } public long ProduitId { get; set; } public long LotId { get; set; } public int Quantite { get; set; } public decimal CoutAchat { get; set; } }
public sealed class SessionCaisse { public long Id { get; set; } public DateTime DateOuverture { get; set; } public DateTime? DateCloture { get; set; } public long UtilisateurId { get; set; } public decimal FondCaisse { get; set; } public decimal? TotalEspecesAttendu { get; set; } public decimal? TotalEspecesCompte { get; set; } public decimal? Ecart { get; set; } public StatutSessionCaisse Statut { get; set; } = StatutSessionCaisse.Ouverte; }
public sealed class MouvementCaisse { public long Id { get; set; } public long SessionId { get; set; } public DateTime DateMouvement { get; set; } public long UtilisateurId { get; set; } public decimal Montant { get; set; } public string Motif { get; set; } = ""; public TypeMouvementCaisse Type { get; set; } }
public sealed class ParametrePharmacie { public string Cle { get; set; } = ""; public string Valeur { get; set; } = ""; }
